insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Cybersecurity avanzata 1: dalla falla al CVE', 'Il ciclo di vita di una vulnerabilità, gli identificativi CVE, il punteggio CVSS 3.1 letto e calcolato, KEV ed EPSS, divulgazione coordinata e bug bounty, con il caso Heartbleed.', 'contenuti/lezioni/vulnerabilita-cve.html', 'contenuti/lezioni/vulnerabilita-cve.pdf', now() - interval '1 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/vulnerabilita-cve.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Cybersecurity avanzata 2: XSS, CSRF e Content Security Policy', 'XSS riflesso, memorizzato e DOM, la codifica dell''output, la Content Security Policy, l''attacco CSRF e le difese con token e cookie SameSite, provati su un guestbook in Java.', 'contenuti/lezioni/xss-csrf-csp.html', 'contenuti/lezioni/xss-csrf-csp.pdf', now() - interval '2 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/xss-csrf-csp.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Cybersecurity avanzata 3: password, hash e salt', 'Perché le password non si salvano in chiaro, SHA-256 e il salt, funzioni lente come PBKDF2, bcrypt e Argon2, il calcolo del tempo di forza bruta, credential stuffing e il controllo con k-anonimato.', 'contenuti/lezioni/password-hash.html', 'contenuti/lezioni/password-hash.pdf', now() - interval '3 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/password-hash.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Cybersecurity avanzata 4: TLS e certificati', 'L''handshake di TLS 1.3 con ECDHE, il certificato X.509 e la catena di fiducia, Certificate Transparency, errori dei certificati provati su siti di test e un keystore con keytool.', 'contenuti/lezioni/tls-certificati.html', 'contenuti/lezioni/tls-certificati.pdf', now() - interval '4 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/tls-certificati.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Cybersecurity avanzata 5: OAuth, JWT e passkey', 'Autenticazione a più fattori, OAuth 2.0 con PKCE e OpenID Connect, la struttura e la verifica di un JWT, WebAuthn e passkey contro il phishing.', 'contenuti/lezioni/oauth-jwt-passkey.html', 'contenuti/lezioni/oauth-jwt-passkey.pdf', now() - interval '5 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/oauth-jwt-passkey.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Cybersecurity avanzata 6: anatomia di un''e-mail', 'SMTP e gli header di una mail, SPF, DKIM e DMARC letti dal DNS, domini sosia e truffe BEC: chi può fingersi un''azienda e come impedirlo.', 'contenuti/lezioni/email-spf-dkim-dmarc.html', 'contenuti/lezioni/email-spf-dkim-dmarc.pdf', now() - interval '6 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/email-spf-dkim-dmarc.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Cybersecurity avanzata 7: Wireshark, leggere il traffico', 'Catturare in modo lecito il proprio traffico, filtri di visualizzazione, DNS e three-way handshake, una password in chiaro su HTTP, che cosa resta visibile con TLS, statistiche e metadati.', 'contenuti/lezioni/wireshark-traffico.html', 'contenuti/lezioni/wireshark-traffico.pdf', now() - interval '7 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/wireshark-traffico.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5g', 'Cybersecurity avanzata 8: informatica forense', 'Le fasi dell''indagine, l''ordine di volatilità, copia forense, hash e catena di custodia, le date dei file, il registro eventi di Windows e una timeline in Calc.', 'contenuti/lezioni/informatica-forense.html', 'contenuti/lezioni/informatica-forense.pdf', now() - interval '8 minutes' where not exists (select 1 from materials where class_id = '5g' and url = 'contenuti/lezioni/informatica-forense.html');
