insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5g', 'L''avviso di sicurezza', 'Sei l''analista di sicurezza di Officine Rossi, l''azienda di esempio della lezione sui cybercriminali. Il direttore ti chiede: "Questa falla ci riguarda? Che cosa facciamo?". Rispondi con un avviso di una pagina. Consegna il file avviso-cognome.pdf (una pagina, al massimo due) su Google Classroom.', null, null, (select id from topics where class_id = '5g' and title = 'Cybersecurity avanzata 1: dalla falla al CVE' limit 1), 'contenuti/compiti/vulnerabilita-cve.pdf', 'compito', false, false where not exists (select 1 from assignments where class_id = '5g' and title = 'L''avviso di sicurezza');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5g', 'Il guestbook blindato', 'Un guestbook è la pagina più semplice del web: chiunque lascia un messaggio, tutti lo leggono. È anche il bersaglio perfetto per un XSS memorizzato. Scrivine uno in Java che resista. Consegna il file guestbook-cognome.zip con Guestbook.java e un README.pdf di una pagina con le schermate, su Google Classroom.', null, null, (select id from topics where class_id = '5g' and title = 'Cybersecurity avanzata 2: XSS, CSRF e Content Security Policy' limit 1), 'contenuti/compiti/xss-csrf-csp.pdf', 'compito', false, false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il guestbook blindato');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5g', 'Il login che non si fa rubare', 'Scrivi in Java il cuore di un sistema di login: registrazione, verifica e un limite ai tentativi. Se domani qualcuno ruba il tuo "database", deve trovarci solo impronte lente e salate. Consegna il file login-cognome.zip con Login.java e un README.pdf di una pagina, su Google Classroom.', null, null, (select id from topics where class_id = '5g' and title = 'Cybersecurity avanzata 3: password, hash e salt' limit 1), 'contenuti/compiti/password-hash.pdf', 'compito', false, false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il login che non si fa rubare');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5g', 'Il controllore dei certificati', 'Un certificato scaduto manda offline un servizio come un guasto. Scrivi il piccolo strumento che un amministratore lancia ogni mattina: legge una lista di siti e avvisa per tempo. Consegna il file certificati-cognome.zip con Controllore.java, il file siti.txt e un README.pdf con l''output e le risposte, su Google Classroom.', null, null, (select id from topics where class_id = '5g' and title = 'Cybersecurity avanzata 4: TLS e certificati' limit 1), 'contenuti/compiti/tls-certificati.pdf', 'compito', false, false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il controllore dei certificati');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5g', 'Un''API con il token', 'Unisci le lezioni: un piccolo web service REST in Java (un anticipo dell''unità 2) che rilascia e controlla JWT firmati (lezione 5), con le password conservate bene (lezione 3). Consegna il file api-token-cognome.zip con il codice Java e un README.pdf con i comandi curl e le risposte, su Google Classroom.', null, null, (select id from topics where class_id = '5g' and title = 'Cybersecurity avanzata 5: OAuth, JWT e passkey' limit 1), 'contenuti/compiti/oauth-jwt-passkey.pdf', 'compito', false, false where not exists (select 1 from assignments where class_id = '5g' and title = 'Un''API con il token');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5g', 'Chi può fingersi te?', 'Un''azienda locale ti chiede: "Qualcuno può mandare mail che sembrano nostre?". Rispondi con un''analisi di cinque domini veri, letta solo dal DNS pubblico, e consigli concreti. Consegna il file posta-cognome.pdf (1-2 pagine) su Google Classroom.', null, null, (select id from topics where class_id = '5g' and title = 'Cybersecurity avanzata 6: anatomia di un''e-mail' limit 1), 'contenuti/compiti/email-spf-dkim-dmarc.pdf', 'compito', false, false where not exists (select 1 from assignments where class_id = '5g' and title = 'Chi può fingersi te?');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5g', 'Il diario di una pagina web', 'Apri una sola pagina web e racconta, pacchetto per pacchetto, che cosa è successo sulla tua rete in quei pochi secondi. Poi confronta con un sito in chiaro che gira sul tuo PC. Consegna il file diario-cognome.pdf (2 pagine, con screenshot) su Google Classroom. Non consegnare il file .pcapng.', null, null, (select id from topics where class_id = '5g' and title = 'Cybersecurity avanzata 7: Wireshark, leggere il traffico' limit 1), 'contenuti/compiti/wireshark-traffico.pdf', 'compito', false, false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il diario di una pagina web');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5g', 'Il caso della chiavetta', 'Un piccolo studio di progettazione sospetta che venerdì sera qualcuno abbia portato via i disegni di un cliente. Il perito ha già acquisito il PC dell''ufficio tecnico (hash verificati) e ti passa gli estratti qui sotto. Il caso è inventato. Consegna il file caso-cognome.pdf (2 pagine) e il foglio timeline-cognome.ods su Google Classroom.', null, null, (select id from topics where class_id = '5g' and title = 'Cybersecurity avanzata 8: informatica forense' limit 1), 'contenuti/compiti/informatica-forense.pdf', 'compito', false, false where not exists (select 1 from assignments where class_id = '5g' and title = 'Il caso della chiavetta');
insert into tests (class_id, position, title, description, test_date, practice_url) select '5g', 15, 'Verifica: cybersecurity avanzata', 'CVE e CVSS, XSS e CSRF, password e hash, TLS, JWT e passkey, SPF e DMARC, Wireshark, informatica forense.', null, 'contenuti/verifiche/5g-cyber-simulazione.pdf' where not exists (select 1 from tests where class_id = '5g' and title = 'Verifica: cybersecurity avanzata');
insert into test_files (test_id, test_url, solutions_url) select id, 'contenuti/verifiche/5g-cyber-verifica-ecc6de5fd4.pdf', 'contenuti/verifiche/5g-cyber-soluzioni-ecc6de5fd4.pdf' from tests where class_id = '5g' and title = 'Verifica: cybersecurity avanzata' on conflict (test_id) do nothing;
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5f', 'Officina 1 · Business Model Canvas', 'L''idea di startup del gruppo sui nove blocchi del Business Model Canvas, le ipotesi da verificare, cinque interviste a clienti veri e il canvas rivisto.', 'contenuti/lezioni/gpoi-officina-canvas.html', 'contenuti/lezioni/gpoi-officina-canvas.pdf', now() - interval '1 minutes' where not exists (select 1 from materials where class_id = '5f' and url = 'contenuti/lezioni/gpoi-officina-canvas.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5f', 'Officina 2 · Mercato e SWOT', 'TAM, SAM e SOM con fonti citate, concorrenti diretti e indiretti, mappa di posizionamento, analisi SWOT e strategie TOWS.', 'contenuti/lezioni/gpoi-officina-mercato.html', 'contenuti/lezioni/gpoi-officina-mercato.pdf', now() - interval '2 minutes' where not exists (select 1 from materials where class_id = '5f' and url = 'contenuti/lezioni/gpoi-officina-mercato.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5f', 'Officina 3 · WBS, OBS e RACI', 'Obiettivo SMART e ambito del progetto di lancio, la WBS orientata ai deliverable con il dizionario, l''OBS del gruppo e la matrice RACI.', 'contenuti/lezioni/gpoi-officina-wbs.html', 'contenuti/lezioni/gpoi-officina-wbs.pdf', now() - interval '3 minutes' where not exists (select 1 from materials where class_id = '5f' and url = 'contenuti/lezioni/gpoi-officina-wbs.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5f', 'Officina 4 · Reticolo CPM e Gantt', 'Stime a tre punti con PERT, precedenze, calcolo in avanti e all''indietro, percorso critico e slack, poi il Gantt in ProjectLibre con risorse e baseline.', 'contenuti/lezioni/gpoi-officina-cpm.html', 'contenuti/lezioni/gpoi-officina-cpm.pdf', now() - interval '4 minutes' where not exists (select 1 from materials where class_id = '5f' and url = 'contenuti/lezioni/gpoi-officina-cpm.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5f', 'Officina 5 · Preventivo, pareggio e rischi', 'La CBS dalla WBS, spese generali e riserva di contingenza, margine di contribuzione e punto di pareggio, registro e matrice dei rischi con il valore atteso.', 'contenuti/lezioni/gpoi-officina-preventivo.html', 'contenuti/lezioni/gpoi-officina-preventivo.pdf', now() - interval '5 minutes' where not exists (select 1 from materials where class_id = '5f' and url = 'contenuti/lezioni/gpoi-officina-preventivo.html');
insert into materials (class_id, title, description, url, pdf_url, created_at) select '5f', 'Officina 6 · Business plan e pitch', 'Le cinque Officine diventano un business plan con executive summary e conto economico a 3 anni, e un pitch di 90 secondi davanti alla classe.', 'contenuti/lezioni/gpoi-officina-pitch.html', 'contenuti/lezioni/gpoi-officina-pitch.pdf', now() - interval '6 minutes' where not exists (select 1 from materials where class_id = '5f' and url = 'contenuti/lezioni/gpoi-officina-pitch.html');
