insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5f', 'Officina 1: il Business Model Canvas', 'La prima consegna del progetto di startup: il modello di business su un foglio, prima e dopo aver parlato con 5 clienti veri. Consegnate un file per gruppo, officina1-gruppo.pdf: canvas v1, note delle 5 interviste (senza nomi), canvas v2 e mezza pagina sui cambiamenti.', null, null, (select id from topics where class_id = '5f' and title = 'Officina 1 · Business Model Canvas' limit 1), 'contenuti/compiti/gpoi-officina-canvas.pdf', 'progetto', true, false where not exists (select 1 from assignments where class_id = '5f' and title = 'Officina 1: il Business Model Canvas');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5f', 'Officina 2: mercato e SWOT', 'Quanto vale il mercato della vostra idea, chi c''è già e dove siete forti o deboli. Consegnate mercato-gruppo.ods (fogli Fonti, Mercato, Concorrenti, SWOT) e officina2-gruppo.pdf (mappa di posizionamento, canvas v3, una pagina di commento).', null, null, (select id from topics where class_id = '5f' and title = 'Officina 2 · Mercato e SWOT' limit 1), 'contenuti/compiti/gpoi-officina-mercato.pdf', 'progetto', true, false where not exists (select 1 from assignments where class_id = '5f' and title = 'Officina 2: mercato e SWOT');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5f', 'Officina 3: WBS, OBS e responsabilità', 'Il progetto di lancio della vostra idea: tutto il lavoro scomposto in pacchetti, chi c''è nel progetto e chi fa che cosa. Consegnate officina3-gruppo.pdf (obiettivo, ambito, WBS, OBS) e wbs-gruppo.ods (fogli Dizionario e RACI).', null, null, (select id from topics where class_id = '5f' and title = 'Officina 3 · WBS, OBS e RACI' limit 1), 'contenuti/compiti/gpoi-officina-wbs.pdf', 'progetto', true, false where not exists (select 1 from assignments where class_id = '5f' and title = 'Officina 3: WBS, OBS e responsabilità');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5f', 'Officina 4: reticolo CPM e Gantt', 'Dalla WBS al calendario: durate stimate, precedenze, percorso critico e margini, poi il Gantt in ProjectLibre. Consegnate cpm-gruppo.ods, gantt-gruppo.pod con la baseline e officina4-gruppo.pdf (reticolo, Gantt, mezza pagina di commento).', null, null, (select id from topics where class_id = '5f' and title = 'Officina 4 · Reticolo CPM e Gantt' limit 1), 'contenuti/compiti/gpoi-officina-cpm.pdf', 'progetto', true, false where not exists (select 1 from assignments where class_id = '5f' and title = 'Officina 4: reticolo CPM e Gantt');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5f', 'Officina 5: preventivo, pareggio e rischi', 'Quanto costa il vostro lancio, quanti clienti servono per non perdere soldi e che cosa può andare storto. Consegnate costi-gruppo.ods (fogli CBS, Pareggio, Rischi) e officina5-gruppo.pdf (grafico del pareggio, matrice dei rischi, una pagina di commento).', null, null, (select id from topics where class_id = '5f' and title = 'Officina 5 · Preventivo, pareggio e rischi' limit 1), 'contenuti/compiti/gpoi-officina-preventivo.pdf', 'progetto', true, false where not exists (select 1 from assignments where class_id = '5f' and title = 'Officina 5: preventivo, pareggio e rischi');
insert into assignments (class_id, title, description, due_date, planned_due, topic_id, pdf_url, kind, group_work, auto_correct) select '5f', 'Officina 6: business plan e pitch', 'Le cinque Officine diventano un documento e un discorso di 90 secondi. Consegnate business-plan-gruppo.pdf con le appendici, piano-gruppo.ods con il conto economico a 3 anni e pitch-gruppo.pdf (testo e slide); il pitch si presenta dal vivo nella giornata del pitch.', null, null, (select id from topics where class_id = '5f' and title = 'Officina 6 · Business plan e pitch' limit 1), 'contenuti/compiti/gpoi-officina-pitch.pdf', 'progetto', true, false where not exists (select 1 from assignments where class_id = '5f' and title = 'Officina 6: business plan e pitch');
