-- 0. Archivio dell'ordine attuale (creato solo alla prima esecuzione) ----------------------------
create table if not exists public.topics_ordine_2026_11_10 as
  select id, class_id, position, title, done, now() as archived_at
  from public.topics where class_id in ('3g', '5f', '5g');
alter table public.topics_ordine_2026_11_10 enable row level security;

